// 只新增独立打开来源段；原Interaction会话和AuthoredNodeSource visitor字节保持原样。
#include "resident/checkpoint/checkpoint_decode_lifecycle.hpp"
#include "born_personal_dialogue_state.hpp"
#include "resident/domains/tasks/task_dynamic_codec.hpp"
#include "resident/domains/tasks/task_dynamic_projection.hpp"
#include "resident/domains/interaction/interaction_source_projection.hpp"
#include <set>
namespace hanmo::resident {namespace {
template<class A>Status binding(A& a,BornPersonalDialoguePlayerReceipt& r){a.field("result_id",r.result_id);a.field("request_actor_id",r.request_actor_id);a.field("request_sequence",r.request_sequence);return a.field("result_revision",r.result_revision);}
template<class A>Status opening(A& a,BornPersonalDialogueOpening& r){a.field("fact_id",r.fact_id);a.field("template_id",r.template_id);a.field("session_id",r.session_id);a.field("listener_actor_id",r.listener_actor_id);a.field("provider_actor_id",r.provider_actor_id);a.field("dialogue_id",r.dialogue_id);a.field("place_id",r.place_id);a.field("birth_fact_id",r.birth_fact_id);a.field("creation_fact_id",r.creation_fact_id);a.field("prototype_id",r.prototype_id);a.field("tick",r.tick);return a.optional("player_receipt",r.player_receipt,[](auto& c,auto& v){return binding(c,v);});}
template<class A>Status state(A& a,BornPersonalDialogueState& s){a.field("version",s.version);if(s.version!=1)return a.reject("UnsupportedBornPersonalDialogueVersion");return dynamic_codec::table(a,"openings",s.openings,[](auto& c,auto& r){return opening(c,r);});}
Status unique(const BoundaryValue& v,std::size_t depth=0){if(depth>CodecVisitor::max_depth)return common_failure("BornPersonalDialogueTooDeep");if(const auto* d=v.as<BoundaryValue::Dict>()){if(d->size()>CodecVisitor::max_items)return common_failure("BornPersonalDialogueTooLarge");std::set<StableId> keys;for(const auto& row:*d){if(!keys.insert(row.first).second)return common_failure("DuplicateBornPersonalDialogueField",row.first);auto r=unique(row.second,depth+1);if(!r.ok)return r;}}if(const auto* a=v.as<BoundaryValue::Array>()){if(a->size()>CodecVisitor::max_items)return common_failure("BornPersonalDialogueTooLarge");for(const auto& row:*a){auto r=unique(row,depth+1);if(!r.ok)return r;}}return common_success();}
}
Status visit_born_personal_dialogues_checkpoint(CodecVisitor& a,BornPersonalDialogueState& s){return state(a,s);}
Status emit_born_personal_dialogues_fields(ProjectionWriter&w,const BornPersonalDialogueState&v){dynamic_projection::Archive a(w);return state(a,const_cast<BornPersonalDialogueState&>(v));}
BoundaryValue encode_born_personal_dialogues(const BornPersonalDialogueState& s){BoundaryValue value;BoundaryProjectionWriter writer(value);auto checked=writer.object("",[&](auto& out){return emit_born_personal_dialogues_fields(out,s);});if(checked.ok)checked=writer.finish();if(!checked.ok){boundary::DecodeFailure failure(checked.error.original.code,checked.error.original.path);failure.error=checked.error;throw failure;}return value;}
Outcome<BornPersonalDialogueState> decode_born_personal_dialogues(const BoundaryValue& v){auto valid=unique(v);if(!valid.ok)return {false,{},valid.error};BornPersonalDialogueState s;dynamic_codec::JsonArchive a(v);valid=state(a,s);if(valid.ok)valid=a.finish();return valid.ok?Outcome<BornPersonalDialogueState>{true,std::move(s),{}}:Outcome<BornPersonalDialogueState>{false,{},valid.error};}
Status emit_born_personal_dialogue_fact_fields(ProjectionWriter&w,const BornPersonalDialogueState&s,const StableId&id,const FactRecord*expected){dynamic_projection::Archive a(w);Status valid;StableId kind;const StableId*actual_id=nullptr;if(const auto*row=s.openings.find(id)){valid=opening(a,const_cast<BornPersonalDialogueOpening&>(*row));kind=born_personal_dialogue_opened_kind;actual_id=&row->fact_id;}else return common_failure("UnknownBornPersonalDialogueFact",id);if(!valid.ok)return valid;if(expected&&(!actual_id||*actual_id!=id||kind!=expected->kind))return common_failure("BornPersonalDialogueFactMismatch",id);w.field("kind",kind);w.text("domain",std::string_view(born_personal_dialogue_module));return w.status();}
Outcome<BoundaryValue> encode_born_personal_dialogue_fact(const BornPersonalDialogueState& s,const StableId& id){BoundaryValue value;BoundaryProjectionWriter writer(value);auto checked=writer.object("",[&](auto& out){return emit_born_personal_dialogue_fact_fields(out,s,id);});if(checked.ok)checked=writer.finish();return checked.ok?Outcome<BoundaryValue>{true,std::move(value),{}}:Outcome<BoundaryValue>{false,{},checked.error};}
}
